"""PET/CT DICOM Quality Control Script=====================================Scans a directory of DICOM files and produces a per-series CSV reportflagging issues that make data unsuitable for research use.Usage:    python petct_qc.py /path/to/dicom/dir -o qc_report.csv    python petct_qc.py /path/to/dicom/dir -o qc_report.csv --verboseRequirements:    pip install pydicom numpy pandas tqdm"""import argparseimport csvimport sysimport warningsfrom collections import defaultdictfrom pathlib import Pathimport numpy as npimport pandas as pdimport pydicomfrom tqdm import tqdmfrom functools import lru_cachewarnings.filterwarnings("ignore", category=UserWarning, module="pydicom")# =========================# Tag definitions# =========================# Tags checked on every file regardless of modalityUNIVERSAL_TAGS = [    "SOPInstanceUID",    "SOPClassUID",    "StudyInstanceUID",    "SeriesInstanceUID",    "Modality",    "PatientID",    "StudyDate",    "SeriesDescription",    "ImagePositionPatient",    "ImageOrientationPatient",    "PixelSpacing",    "SliceThickness",    "Rows",    "Columns",    "BitsAllocated",    "BitsStored",    "PixelRepresentation",    "RescaleSlope",    "RescaleIntercept",]# Tags required for SUV calculation and PET quantificationPET_CRITICAL_TAGS = [    "RadiopharmaceuticalInformationSequence",  # contains dose + injection time    "DecayCorrection",          # must be 'START' or 'ADMIN'    "CorrectedImage",           # should include ATTN and DECY    "Units",                    # should be 'BQML' for raw or 'GML' for SUV    "AcquisitionTime",    "ActualFrameDuration",    "PatientWeight",            # needed for SUVbw]# Sub-tags inside RadiopharmaceuticalInformationSequencePET_RADIOPHARM_SUBTAGS = [    "RadionuclidePositronFraction",    "RadionuclideTotalDose",    # injected dose    "RadiopharmaceuticalStartTime",    "RadionuclideHalfLife",    "Radiopharmaceutical",]# Tags that characterise reconstruction, needed to assess cross-subject comparabilityPET_RECONSTRUCTION_TAGS = [    "ReconstructionMethod",    "ConvolutionKernel",    "FilterType",    "NumberOfIterations",    "NumberOfSubsets",]CT_CRITICAL_TAGS = [    "KVP",    "XRayTubeCurrent",    "ExposureTime",    "ConvolutionKernel",    "ReconstructionDiameter",    "DataCollectionDiameter",    "TableHeight",    "GantryDetectorTilt",]# https://dicom.nema.org/medical/dicom/current/output/chtml/part03/sect_c.8.9.htmlACCEPTED_UNITS = [    "BQML",    "GML",    "CNTS",    "CPS",    "ECAT",    "PCNT",    "ML/MIN/G",    "UMOLMINML",    "MLMING",    "MLG",    "PROPCNTS",    "MLMINML",    "MLML",    "GML",    "STDDEV"]# =========================# Helpers# =========================def safe_get(ds, tag_name, default=None):    """Return tag value or default without raising errors."""    try:        return getattr(ds, tag_name, default)    except Exception:        return defaultdef tag_present(ds, tag_name):    """True if tag exists and has a non-empty value."""    val = safe_get(ds, tag_name)    if val is None:        return False    if isinstance(val, (str, bytes)) and not str(val).strip():        return False    return True@lru_cache(maxsize=2000)def read_header(path: str):    """Fast header-only read, cached. Use for all tag checks."""    try:        return pydicom.dcmread(path, stop_before_pixels=True, force=True), None    except Exception as e:        return None, str(e)def read_pixels(path: str):    """Full read only when pixel checks are needed."""    try:        return pydicom.dcmread(path, stop_before_pixels=False, force=True), None    except Exception as e:        return None, str(e)def load_file(path):    """    Try to load a DICOM file. Returns (dataset, error_string).    Dataset is a pydicom.dataset.FileDataset object, which lets access to tags.    Reads pixel data header only for speed; pixel array loaded separately.    """    try:        ds = pydicom.dcmread(str(path), stop_before_pixels=False, force=True)        return ds, None    except Exception as e:        return None, str(e)def check_pixel_data(ds):    """    Attempt to decode pixel data and run sanity checks.    Returns a list of problem strings (empty = OK).    """    problems = []    if not hasattr(ds, "PixelData"):        problems.append("PixelData tag absent")        return problems    try:        arr = ds.pixel_array        if arr.size == 0:            problems.append("Pixel array is empty (zero size)")        elif arr.max() == arr.min():            problems.append(f"Pixel array is flat (all values = {arr.max()})")        if np.isnan(arr.astype(float)).any():            problems.append("Pixel array contains NaN values")    except Exception as e:        problems.append(f"Cannot decode pixel data: {e}")    return problemsdef check_slice_spacing(positions: list):    """    Given a sorted list of Z positions (floats), check for consistent spacing.    Returns a problem string or None.    """    if len(positions) < 3:        return None    gaps = np.diff(sorted(positions))    if len(gaps) == 0:        return None    median_gap = np.median(np.abs(gaps))    if median_gap < 1e-6:        return "All slices at same Z position (duplicate slices?)"    deviations = np.abs(np.abs(gaps) - median_gap)    if np.max(deviations) > 0.5:  # >0.5 mm deviation from median spacing        return (            f"Inconsistent slice spacing (median={median_gap:.2f} mm, "            f"max deviation={np.max(deviations):.2f} mm) ~ possible missing slices"        )    return Nonedef check_pet_suv(ds):    """    Checks PET for whether all tags needed for SUV calculation are present and sensible.    Returns list of problem strings.    """    problems = []    # Patient weight    weight = safe_get(ds, "PatientWeight")    if weight is None:        problems.append("Missing PatientWeight (needed for SUVbw)")    elif float(str(weight)) < 4 or float(str(weight)) > 700:        problems.append(f"PatientWeight={weight} seems implausible")    # Decay correction    # NOTE: Delete later    # START ~ acquisition start time    # ADMIN ~ radiopharmaceutical administration time    # NONE ~ no decay correction    decay = safe_get(ds, "DecayCorrection")    if decay is None:        problems.append("Missing DecayCorrection")    elif str(decay).upper() not in ("START", "ADMIN", "NONE"):        problems.append(f"Unexpected DecayCorrection value: '{decay}'")    # Check if units exist/are commonly used    units = safe_get(ds, "Units")    if units is None:        problems.append("Missing Units tag")    elif str(units).upper() not in ACCEPTED_UNITS:        problems.append(f"Unexpected Units value: '{units}'")    # CorrectedImage, checks if ATTN and DECY are present    corrected = safe_get(ds, "CorrectedImage")    if corrected is None:        problems.append("Missing CorrectedImage tag")    else:        corrected_vals = [str(c).upper() for c in corrected] if hasattr(corrected, "__iter__") else [str(corrected).upper()]        if "ATTN" not in corrected_vals:            problems.append("Attenuation correction (ATTN) not listed in CorrectedImage")        if "DECY" not in corrected_vals:            problems.append("Decay correction (DECY) not listed in CorrectedImage")    # RadiopharmaceuticalInformationSequence    rx_seq = safe_get(ds, "RadiopharmaceuticalInformationSequence")    if rx_seq is None or len(rx_seq) == 0:        problems.append("Missing RadiopharmaceuticalInformationSequence")    else:        rx = rx_seq[0]        dose = safe_get(rx, "RadionuclideTotalDose")        if dose is None:            problems.append("Missing RadionuclideTotalDose (injected dose) in RadiopharmaceuticalInformationSequence")        elif float(str(dose)) <= 0:            problems.append(f"RadionuclideTotalDose={dose} is zero or negative")        start_time = safe_get(rx, "RadiopharmaceuticalStartTime")        if start_time is None:            problems.append("Missing RadiopharmaceuticalStartTime in RadiopharmaceuticalInformationSequence")        half_life = safe_get(rx, "RadionuclideHalfLife")        if half_life is None:            problems.append("Missing RadionuclideHalfLife in RadiopharmaceuticalInformationSequence")        radiopharm = safe_get(rx, "Radiopharmaceutical")        if radiopharm is None:            problems.append("Missing Radiopharmaceutical name in RadiopharmaceuticalInformationSequence")    # AcquisitionTime is needed to compute time-from-injection    if not tag_present(ds, "AcquisitionTime"):        problems.append("Missing AcquisitionTime")    return problemsdef check_reconstruction(ds, modality):    """    Check reconstruction metadata completeness. Returns list of problem strings.    """    problems = []    tags = PET_RECONSTRUCTION_TAGS # if modality == "PT" else ["ConvolutionKernel"]    for tag in tags:        if not tag_present(ds, tag):            problems.append(f"Missing {tag}")    return problems# =========================# Per-file analysis# =========================def analyse_file(path):    """    Load one DICOM file and return a dict of findings.    """    result = {        "filepath": str(path),        "readable": True,        "read_error": "",        "modality": "",        "series_uid": "",        "study_uid": "",        "patient_id": "",        "study_date": "",        "series_description": "",        "image_position_z": None,        "universal_missing": [],        "pixel_problems": [],        "pet_suv_problems": [],        "pet_reconstruction_problems": [],        "ct_tag_problems": [],        "raw_ds": None,   # kept temporarily for series-level checks    }    ds, err = load_file(path)    if ds is None:        result["readable"] = False        result["read_error"] = err        return result    # Add the tag infomration from dataset to the dictionary    result["raw_ds"] = ds    result["modality"] = str(safe_get(ds, "Modality", ""))    result["series_uid"] = str(safe_get(ds, "SeriesInstanceUID", ""))    result["study_uid"] = str(safe_get(ds, "StudyInstanceUID", ""))    result["patient_id"] = str(safe_get(ds, "PatientID", ""))    result["study_date"] = str(safe_get(ds, "StudyDate", ""))    result["series_description"] = str(safe_get(ds, "SeriesDescription", ""))    # Get ImagePositionPatient (Coordinate of upper left corner of slice)    pos = safe_get(ds, "ImagePositionPatient")    if pos is not None:        try:            result["image_position_z"] = float(pos[2])        except Exception:            pass    # Universal tag check    for tag in UNIVERSAL_TAGS:        if not tag_present(ds, tag):            result["universal_missing"].append(tag)    # Pixel data check ~ Pydicom uses an image decoder that does NOT work on MacOS    # ⚑    # Check_pixel_data() function looks for object ds.pixel_array    result["pixel_problems"] = check_pixel_data(ds)    result["pixel_problems"] = None    # Modality-specific checks    modality = result["modality"]    if modality == "PT":        result["pet_suv_problems"] = check_pet_suv(ds)        result["pet_reconstruction_problems"] = check_reconstruction(ds, "PT")    elif modality == "CT":        ct_missing = []        for tag in CT_CRITICAL_TAGS:            if not tag_present(ds, tag):                ct_missing.append(f"Missing {tag}")        result["ct_tag_problems"] = ct_missing    return result# =========================# Series-level aggregation ~ Adds the file results into a row# It accounts for unreadable files and appends readable files to the series map# =========================def aggregate_series(file_results: list) -> list:    """    Group file-level results by SeriesInstanceUID and produce one row per series.    """    series_map = defaultdict(list)    unreadable = []    for r in file_results:        if not r["readable"]:            unreadable.append(r)        else:            series_map[r["series_uid"]].append(r)    rows = []    # Unreadable files get their own rows    for r in unreadable:        rows.append({            "series_uid":             "UNKNOWN",            "study_uid":              "UNKNOWN",            "patient_id":             "UNKNOWN",            "study_date":             "UNKNOWN",            "modality":               "UNKNOWN",            "series_description":     "UNKNOWN",            "num_files":              1,            "suv_calculable":         "N/A",            "pixel_ok":               "FAIL",            "reconstruction_info_ok": "N/A",            "ct_protocol_ok":         "N/A",            "slice_spacing_ok":       "N/A",            "overall_status":         "FAIL",            "issues":                 f"File unreadable: {r['read_error']}",            "example_file":           r["filepath"],        })    for uid, files in series_map.items():        rep = files[0]  # representative file for series-level metadata        all_issues = []        # Collect all unique problems across files in the series in sets and append to issues list        universal_missing = set()        pixel_probs = set()        pet_suv_probs = set()        pet_recon_probs = set()        ct_probs = set()        for f in files:            universal_missing.update(f["universal_missing"])            pixel_probs.update(f["pixel_problems"])            pet_suv_probs.update(f["pet_suv_problems"])            pet_recon_probs.update(f["pet_reconstruction_problems"])            ct_probs.update(f["ct_tag_problems"])        if universal_missing:            all_issues.append(f"Missing universal tags: {', '.join(sorted(universal_missing))}")        if pixel_probs:            all_issues.extend(sorted(pixel_probs))        # Check slice spacing and append to issues if problem        z_positions = [f["image_position_z"] for f in files if f["image_position_z"] is not None]        spacing_problem = check_slice_spacing(z_positions)        slice_ok = "PASS"        if spacing_problem:            all_issues.append(spacing_problem)            slice_ok = "WARN"        elif len(z_positions) < 2:            slice_ok = "N/A"        modality = rep["modality"]        # SUV status        suv_ok = "N/A"        if modality == "PT":            if pet_suv_probs:                all_issues.extend(sorted(pet_suv_probs))                suv_ok = "FAIL"            else:                suv_ok = "PASS"        # Reconstruction info        recon_ok = "N/A"        if modality in ("PT", "CT"):            if pet_recon_probs or ct_probs:                all_issues.extend(sorted(pet_recon_probs))                all_issues.extend(sorted(ct_probs))                recon_ok = "WARN"            else:                recon_ok = "PASS"        # CT protocol        ct_ok = "N/A"        if modality == "CT":            ct_ok = "FAIL" if ct_probs else "PASS"        # Pixel status        pixel_ok = "FAIL" if pixel_probs else "PASS"        # Overall status        # If P        if pixel_ok == "FAIL" or suv_ok == "FAIL":            overall = "FAIL"        elif suv_ok == "WARN" or recon_ok == "WARN" or slice_ok == "WARN" or ct_ok == "FAIL":            overall = "WARN"        else:            overall = "PASS"        rows.append({            "series_uid":             uid,            "study_uid":              rep["study_uid"],            "patient_id":             rep["patient_id"],            "study_date":             rep["study_date"],            "modality":               modality,            "series_description":     rep["series_description"],            "num_files":              len(files),            "suv_calculable":         suv_ok,            "pixel_ok":               pixel_ok,            "reconstruction_info_ok": recon_ok,            "ct_protocol_ok":         ct_ok,            "slice_spacing_ok":       slice_ok,            "overall_status":         overall,            "issues":                 " | ".join(all_issues) if all_issues else "None",            "example_file":           rep["filepath"],        })    return rows# =========================# CT/PET pairing check# =========================def check_pet_ct_pairing(rows):    """    For each PET series, check whether a CT series exists in the same study.    Adds a 'paired_ct' column to each row.    """    study_modalities = defaultdict(set)    for row in rows:        study_modalities[row["study_uid"]].add(row["modality"])    for row in rows:        if row["modality"] == "PT":            has_ct = "CT" in study_modalities[row["study_uid"]]            row["paired_ct"] = "YES" if has_ct else "No CT series found in study"            if not has_ct:                if row["issues"] == "None":                    row["issues"] = "No paired CT series in study"                else:                    row["issues"] += " | No paired CT series in study"                if row["overall_status"] == "PASS":                    row["overall_status"] = "WARN"        else:            row["paired_ct"] = "N/A"    return rows# =========================# Main# =========================def main():    parser = argparse.ArgumentParser(        description="PET/CT DICOM Quality Control ~ produces a per-series CSV report."    )    parser.add_argument("dicom_dir", help="Root directory containing DICOM files")    parser.add_argument("-o", "--output", default="qc_report.csv",                        help="Output CSV file path (default: qc_report.csv)")    parser.add_argument("--verbose", action="store_true",                        help="Print per-series issues to stdout as well")    args = parser.parse_args()    dicom_dir = Path(args.dicom_dir)    if not dicom_dir.exists():        print(f"ERROR: Directory not found: {dicom_dir}", file=sys.stderr)        sys.exit(1)    # Collect candidate files in the dicom directory    candidates = [p for p in dicom_dir.rglob("*") if p.is_file()]    print(f"Found {len(candidates)} files under {dicom_dir}")    # Per-file analysis using analyse_file function, uses tqdm to print progress bar    # As it appens to file results list    file_results = []    for path in tqdm(candidates, desc="Analysing files", unit="file"):        file_results.append(analyse_file(path))    # Drop non-DICOM files (readable but no SeriesInstanceUID and no modality)    # ⚑ This would append nonreadable to dicom results    dicom_results = [        r for r in file_results        if not r["readable"] or r["series_uid"] not in ("", "None")    ]    skipped = len(file_results) - len(dicom_results)    if skipped:        print(f"Skipped {skipped} non-DICOM files")    if not dicom_results:        print("No DICOM files found. Exiting.")        sys.exit(0)    # Aggregate to series level    rows = aggregate_series(dicom_results)    # PET/CT pairing check    rows = check_pet_ct_pairing(rows)    # Sort: FAILs first, then WARNs, then PASSes; within each group by study/series    status_order = {"FAIL": 0, "WARN": 1, "PASS": 2, "N/A": 3}    rows.sort(key=lambda r: (        status_order.get(r["overall_status"], 9),        r["study_uid"],        r["series_uid"],    ))    # Write CSV    fieldnames = [        "overall_status", "modality", "patient_id", "study_date",        "series_description", "num_files", "suv_calculable", "pixel_ok",        "reconstruction_info_ok", "ct_protocol_ok", "slice_spacing_ok",        "paired_ct", "issues", "series_uid", "study_uid", "example_file",    ]    output_path = Path(args.output)    with open(output_path, "w", newline="", encoding="utf-8") as f:        writer = csv.DictWriter(f, fieldnames=fieldnames)        writer.writeheader()        writer.writerows(rows)    # Summary    total = len(rows)    n_fail = sum(1 for r in rows if r["overall_status"] == "FAIL")    n_warn = sum(1 for r in rows if r["overall_status"] == "WARN")    n_pass = sum(1 for r in rows if r["overall_status"] == "PASS")    n_pet = sum(1 for r in rows if r["modality"] == "PT")    n_ct = sum(1 for r in rows if r["modality"] == "CT")    print(f"\n{'='*60}")    print(f"  QC REPORT SUMMARY")    print(f"{'='*60}")    print(f"  Total series analysed : {total}")    print(f"  PET series            : {n_pet}")    print(f"  CT series             : {n_ct}")    print(f"  PASS                  : {n_pass}")    print(f"  WARN                  : {n_warn}")    print(f"  FAIL                  : {n_fail}")    print(f"{'='*60}")    print(f"  Report saved to: {output_path.resolve()}")    if args.verbose:        print("\nDetailed issues:\n")        for r in rows:            if r["overall_status"] in ("FAIL", "WARN"):                print(f"  [{r['overall_status']}] {r['modality']} | {r['patient_id']} | "                      f"{r['series_description']} | {r['issues']}")if __name__ == "__main__":    main()